package com.example.domain.model.i18n

/** Machine translated draft; religious and linguistic review pending. */
internal object DuaThDraft6 {
    val MAP: Map<String, DuaText> = mapOf(
        "dua_sharri_ma_amiltu" to DuaText("หลบภัยจากความชั่วร้ายแห่งการกระทำของฉัน", "โอ้อัลลอฮ์ ฉันขอความคุ้มครองต่อพระองค์ให้พ้นจากความชั่วร้ายของสิ่งที่ฉันได้ทำ และความชั่วร้ายของสิ่งที่ฉันยังไม่ได้ทำ", "Dua ของศาสดา ﷺ ตาม Aisha (RA)", "การคุ้มครองจากผลของทั้งสิ่งที่ทำและสิ่งที่ถูกละเลย"),
        "dua_jahdil_bala" to DuaText("ที่ลี้ภัยจากการทดลองอันแสนสาหัส", "โอ้อัลลอฮ์ ฉันขอความคุ้มครองจากพระองค์ให้พ้นจากการทดลองอันหนักหน่วง จากการถูกครอบงำด้วยความทุกข์ยาก จากคำสั่งที่ชั่วร้าย และจากความยินดีของศัตรู", "หลบภัยจากการทดลองอันโหดร้ายและความยินดีของศัตรู", "พระศาสดา ﷺ ขอความคุ้มครองจากสี่สิ่งนี้"),
        "dua_fitnat_ghina_faqr" to DuaText("ที่ลี้ภัยจากการทดสอบความมั่งคั่งและความยากจน", "โอ้อัลลอฮ์ ฉันขอความคุ้มครองจากพระองค์ให้พ้นจากความเกียจคร้านและความชรา จากบาปและหนี้ จากการทดสอบและการลงโทษในหลุมศพ จากการทดสอบและการลงโทษแห่งไฟ จากความชั่วร้ายของการทดสอบความมั่งคั่ง และจากการทดสอบความยากจน", "ให้พ้นจากการทดลองในหลุมศพ นรก ความมั่งคั่ง และความยากจน (ส่วนหนึ่งของดุอา)", "Dua ที่หลบภัยที่ครอบคลุมจากศาสดา ﷺ"),
        "dua_kufr_faqr" to DuaText("ขอลี้ภัยจากความไม่เชื่อและความยากจน", "โอ้อัลลอฮ์ ฉันขอความคุ้มครองต่อพระองค์จากการปฏิเสธศรัทธาและความยากจน และฉันขอความคุ้มครองต่อพระองค์ให้พ้นจากการลงโทษในหลุมศพ ไม่มีพระเจ้าอื่นใดนอกจากพระองค์", "สามครั้งเช้าและเย็น", "อบู บักเราะห์ (RA) ได้ยินท่านศาสดา ﷺ พูดเช่นนี้"),
        "dua_sharri_sami" to DuaText("หลบภัยจากความชั่วร้ายแห่งความรู้สึกของฉัน", "โอ้อัลลอฮ์ ฉันขอความคุ้มครองต่อพระองค์ให้พ้นจากความชั่วในการได้ยินของฉัน ความชั่วในการมองเห็นของฉัน ความชั่วแห่งลิ้นของฉัน ความชั่วในจิตใจของฉัน และความชั่วร้ายในความปรารถนาของฉัน", "สอนให้ชากัล บิน ฮุมัยด์ (RA)", "ดุอาเพื่อปกป้องแขนขาและตนเองจากบาป"),
        "dua_hadm_gharaq" to DuaText("ที่หลบภัยจากการเสียชีวิตกะทันหันและอุบัติเหตุ", "โอ้อัลลอฮ์ ฉันขอความคุ้มครองต่อพระองค์จากการถูกพังทลาย (จากอาคาร) จากการตกจากที่สูง จากการจมน้ำ การถูกไฟไหม้ และวัยชรา จากชัยฏอนทำให้ฉันหลงทางในเวลาแห่งความตาย จากการตายขณะหนีจากทางของพระองค์ และจากการตายด้วยเหล็กไน (มีพิษ)", "ที่หลบภัยจากอุบัติเหตุและการเสียชีวิตอันแสนสาหัส", "ดุอาขอความคุ้มครองจากท่านศาสดา ﷺ"),
        "dua_ju_khiyanah" to DuaText("ที่ลี้ภัยจากความหิวโหยและการทรยศ", "โอ้อัลลอฮ์ ฉันขอความคุ้มครองจากพระองค์ให้พ้นจากความหิวโหย เพราะมันเป็นเพื่อนที่ชั่วร้าย และฉันขอความคุ้มครองต่อพระองค์จากการทรยศ เพราะมันเป็นเพื่อนที่ชั่วร้าย", "หลบภัยจากความหิวโหยและการทรยศ", "ดุอาขอความคุ้มครองจากท่านศาสดา ﷺ"),
        "dua_huda_tuqa" to DuaText("การชี้นำ ความกตัญญู พรหมจรรย์ และความพอเพียง", "โอ้อัลลอฮฺ ฉันขอคำแนะนำจากพระองค์ ความยำเกรง ความบริสุทธิ์ และการพึ่งพาตนเอง", "ดุอาสั้น ๆ ที่ครอบคลุมของศาสดาพยากรณ์ ﷺ", "พรพื้นฐานสี่ประการของศาสนาและโลกนี้"),
        "dua_aslih_li_dini" to DuaText("แก้ไขศาสนาของฉัน โลกและปรโลก", "โอ้อัลลอฮ์ โปรดทรงทำให้ศาสนาของฉันถูกต้อง ซึ่งเป็นเครื่องปกป้องกิจการของฉันทั้งหมด กำหนดชีวิตทางโลกของฉันซึ่งเป็นอาชีพของฉันให้ถูกต้อง และกำหนดปรโลกของฉันให้เรียบร้อย ซึ่งฉันจะกลับไป ขอทรงให้ชีวิตเพิ่มขึ้นแก่ข้าพระองค์ในความดีทุกอย่าง และทรงให้ความตายช่วยข้าพระองค์ให้พ้นจากความชั่วทุกอย่าง", "ปฏิรูปศาสนา โลกนี้ และโลกหน้า ทั้งสามประการ", "Dua ที่ครอบคลุมของศาสดา ﷺ"),
        "dua_musarrifal_qulub" to DuaText("หันใจของเราไปสู่การเชื่อฟังของคุณ", "โอ้อัลลอฮ์ ผู้พลิกดวงใจ โปรดหันหัวใจของเราไปสู่การเชื่อฟังของพระองค์", "ดุอาเพื่อให้หัวใจมั่นคงในการเชื่อฟัง", "หัวใจของทุกคนอยู่ระหว่างสองนิ้วของผู้ทรงเมตตาเสมอ"),
        "dua_jannah_nar" to DuaText("ขอญานนาห์ ให้พ้นจากไฟ", "โอ้อัลลอฮฺ ฉันขอความคุ้มครองจากพระองค์ และฉันขอความคุ้มครองต่อพระองค์ให้พ้นจากไฟนรก", "หลังตะชะหุดหรือเวลาใดก็ได้", "ศาสดา ﷺ กล่าวว่า: Duas ของเราก็หมุนรอบเรื่องนี้เช่นกัน"),
        "dua_khayri_kullih" to DuaText("ดีทั้งหมดตอนนี้และในภายหลัง", "โอ้อัลลอฮ์ ฉันขอความโปรดปรานจากพระองค์ทั้งที่เกิดขึ้นทันทีและล่าช้า สิ่งที่ฉันรู้และสิ่งที่ฉันไม่รู้ และฉันขอความคุ้มครองจากพระองค์ให้พ้นจากความชั่วร้ายทั้งที่เกิดขึ้นทันทีและล่าช้า สิ่งที่ฉันรู้และสิ่งที่ฉันไม่รู้ โอ้ อัลลอฮฺ ฉันขอความคุ้มครองต่อพระองค์สำหรับสวรรค์ และคำพูดและการกระทำใดๆ ที่ทำให้ฉันเข้าใกล้มัน และฉันขอความคุ้มครองต่อพระองค์ให้พ้นจากไฟนรก และจากคำพูดและการกระทำใดๆ ก็ตามที่ทำให้ฉันเข้าใกล้มัน", "ศาสดา ﷺ สอน Dua ที่ครอบคลุมนี้ให้กับ Aisha (RA) (ส่วนหนึ่งของ Dua)", "ดุอาที่รวบรวมความดีทุกอย่าง"),
        "dua_ihdini_saddidni" to DuaText("ขอทรงนำทางข้าพระองค์และทรงรักษาข้าพระองค์ให้เที่ยงตรง", "โอ้อัลลอฮ์ ขอทรงแนะนำฉัน และให้ฉันอยู่ในแนวทางที่ถูกต้อง", "ศาสดาพยากรณ์ ﷺ สอนเรื่องนี้แก่อาลี (RA)", "คิดว่าการนำทางเป็นเหมือนการนำทางไปตามถนน และซาดัดเป็นเหมือนลูกศรที่ตรง"),
        "dua_hubbaka" to DuaText("การขอความรักจากอัลลอฮ", "โอ้อัลลอฮ์ ฉันขอความรักจากพระองค์ ความรักของผู้ที่รักพระองค์ และการกระทำที่นำฉันไปสู่ความรักของพระองค์ โอ้อัลลอฮ์ โปรดทำให้ความรักของพระองค์เป็นที่รักของฉันมากกว่าตัวฉันเอง ครอบครัวของฉัน และน้ำเย็น", "ดุอาของดาวุด (AS) เกี่ยวข้องกับท่านศาสดา ﷺ", "ความรักของอัลลอฮ์นั้นเป็นความมั่งคั่งที่ยิ่งใหญ่ที่สุด"),
        "dua_filal_khayrat" to DuaText("การทำความดีและละความชั่ว", "โอ้อัลลอฮฺ ฉันขอวิงวอนต่อพระองค์เพื่อให้ฉันทำความดี ละทิ้งความชั่ว และรักคนยากจน และขอพระองค์ทรงอภัยโทษให้ฉัน และทรงเมตตาฉันด้วย และเมื่อพระองค์ทรงประสงค์จะทดสอบชนชาติใด โปรดพาข้าพระองค์ไปโดยไม่มีใครถูกทดลอง ข้าพระองค์ขอความรักจากพระองค์ ความรักของผู้ที่รักพระองค์ และความรักในการกระทำที่นำข้าพระองค์เข้าใกล้ความรักของพระองค์", "อัลลอฮ์ทรงสอนดุอานี้แก่ท่านศาสดาพยากรณ์ ﷺ ในความฝัน", "ศาสดา ﷺ กล่าวว่า: มันเป็นความจริง ดังนั้นจงเรียนรู้และสอนมัน"),
        "dua_bi_ilmikal_ghayb" to DuaText("ให้ฉันมีชีวิตอยู่ในขณะที่ชีวิตเป็นสิ่งที่ดี", "โอ้อัลลอฮ์ ด้วยความรู้ที่พระองค์ทรงรู้ถึงสิ่งเร้นลับและอำนาจเหนือสรรพสิ่งของพระองค์ โปรดให้ฉันมีชีวิตอยู่ตราบเท่าที่พระองค์ทรงรู้ว่าชีวิตดีกว่าสำหรับฉัน และพาฉันไปเมื่อพระองค์ทรงรู้ว่าความตายดีกว่าสำหรับฉัน โอ้อัลลอฮฺ ฉันขอวิงวอนต่อพระองค์ทั้งในที่ส่วนตัวและในที่สาธารณะ สำหรับพระวจนะแห่งความจริงด้วยความพอใจและความโกรธ และเพื่อความพอประมาณในความยากจนและความมั่งคั่ง", "บทสวดมนต์ของอัมมาร์ อิบนุ ยาซิร (RA) (ตอนเปิด)", "ศาสดา ﷺ ทำ dua นี้ในการอธิษฐาน"),
        "dua_ism_azam_mannan" to DuaText("อิสม์อีอะซาม: อัล-มานนัน", "โอ้อัลลอฮฺ ฉันขอวิงวอนต่อพระองค์ เพราะบรรดาการสรรเสริญเป็นของพระองค์ ไม่มีพระเจ้าอื่นใดนอกจากพระองค์ ผู้ทรงประทานความกรุณา ผู้ทรงสร้างชั้นฟ้าทั้งหลายและแผ่นดิน ข้าแต่ผู้ครอบครองแห่งความยิ่งใหญ่และเกียรติยศ ข้าผู้ดำรงอยู่ตลอดกาล ข้าแต่ผู้ค้ำจุน!", "ศาสดา ﷺ กล่าวว่าชายคนนี้ทำ dua ด้วยพระนามที่ยิ่งใหญ่ที่สุดของอัลลอฮ์", "ดุอาที่ทำขึ้นด้วยชื่อนี้จะได้รับคำตอบ"),
        "dua_ism_azam_ahad_samad" to DuaText("อิสม์เออะซัม: อัลอะฮัด อัส-สะหมัด", "โอ้อัลลอฮฺ ฉันขอวิงวอนต่อพระองค์ เพราะฉันขอปฏิญาณว่าพระองค์คืออัลลอฮ์ ไม่มีพระเจ้าอื่นใดนอกจากพระองค์ ผู้ทรงเป็นหนึ่งเดียว ผู้พอเพียง ที่ไม่เกิดหรือเกิด และไม่มีผู้ใดเทียบเคียงได้กับพระองค์", "ศาสดา ﷺ กล่าวว่าชายคนนี้ถามอัลลอฮ์ด้วยพระนามที่ยิ่งใหญ่ที่สุดของพระองค์", "เมื่อถูกขอ พระองค์ทรงให้ เมื่อพระองค์ทรงเรียก พระองค์ก็ทรงตอบ"),
        "dua_thabbitni_hadiyan" to DuaText("ทำให้ฉันมั่นคง นำทาง และนำทาง", "โอ้อัลลอฮ์ โปรดทำให้ฉันมั่นคง และทำให้ฉันเป็นผู้ชี้นำและได้รับคำแนะนำ", "พระศาสดา ﷺ ทำดุอานี้ให้กับจารีร์ (RA) (สำหรับตัวคุณเองพูดว่า 'ทับบิทนี')", "ดุอาดั้งเดิมของจารีร์ (RA) ใช้คำว่า 'thabbit-hu'"),
        "dua_rabbighfir_tub_alayya" to DuaText("โปรดยกโทษให้ฉันและยอมรับการกลับใจของฉัน", "พระเจ้าของฉัน โปรดยกโทษให้ฉันและยอมรับการกลับใจของฉันด้วย แท้จริงพระองค์คือผู้ทรงรับการสำนึกผิด ผู้ทรงเมตตาเสมอ", "ร้อยครั้งในการนั่งครั้งเดียว - การปฏิบัติของศาสดาพยากรณ์ ﷺ", "สหายนับศาสดาพยากรณ์ ﷺ พูดร้อยครั้งในคราวเดียว"),
        "dua_rafiq_ala" to DuaText("ดุอาอฺของบุคคลที่กำลังจะตาย", "โอ้อัลลอฮ์ โปรดยกโทษให้ฉัน โปรดเมตตาฉัน และร่วมกับฉันกับสหายสูงสุด", "ดุอาสุดท้ายของพระศาสดา ﷺ — เพื่อให้คนป่วยพูดด้วยตนเอง", "พระศาสดาหมายเลข ﷺ ทรงดุอาอฺนี้ในเวลาที่ท่านมรณะภาพ"),
        "dua_la_bas_tahur" to DuaText("การปลอบโยนผู้ป่วย: การทำให้บริสุทธิ์", "ไม่มีอันตราย; มันเป็นการชำระล้าง (จากบาป) หากอัลลอฮ์ทรงประสงค์", "เพื่อปลอบโยนผู้ป่วยเมื่อมาเยือน", "พระศาสดา ﷺ กล่าวเช่นนี้เมื่อไปเยี่ยมผู้ป่วย"),
        "dua_talqeen" to DuaText("Talqeen สำหรับผู้กำลังจะตาย", "ไม่มีผู้ใดควรได้รับการสักการะนอกจากอัลลอฮ์", "อ่านคาลิมะห์ใกล้กับบุคคลที่กำลังจะตาย (อย่าบังคับให้พวกเขาพูด)", "ใครก็ตามที่กล่าวคำว่า 'ลาอิลาฮะ อิลลัลลอฮฺ' จะได้เข้าสวรรค์ (อบูดาวูด 3116)"),
        "dua_ahyini_ma_kanat" to DuaText("แทนที่จะปรารถนาความตาย", "โอ้อัลลอฮ์ โปรดให้ฉันมีชีวิตอยู่ตราบใดที่ชีวิตยังดีสำหรับฉัน และโปรดพาฉันไปเมื่อความตายดีกว่าสำหรับฉัน", "แทนที่จะปรารถนาความตายอย่างยากลำบาก", "พระศาสดา ﷺ ห้ามไม่ให้ปรารถนาความตายและสอนสิ่งนี้แทน"),
        "dua_for_one_i_cursed" to DuaText("สำหรับคนที่ฉันเจ็บปวดด้วยคำพูด", "โอ้อัลลอฮ์ ผู้ศรัทธาคนใดที่ฉันดูหมิ่น โปรดทำให้สิ่งนั้นเป็นหนทางใกล้พระองค์สำหรับเขาในวันกิยามะฮ์", "สำหรับคนที่คุณพูดไม่ดีด้วยความโกรธ", "ดุอาของท่านศาสดา ﷺ"),
        "dua_praising_someone" to DuaText("เมื่อชื่นชมใครสักคน", "ฉันถือว่าเป็นเช่นนั้น และอัลลอฮ์เป็นผู้ชำระบัญชีของเขา และฉันไม่รับรองความบริสุทธิ์ของผู้ใดต่ออัลลอฮฺ", "เมื่อชมเชยใครสักคนแทนที่จะพูดเกินจริง", "ศาสดาพยากรณ์ ﷺ สอนมารยาทในการสรรเสริญนี้"),
        "dua_being_praised" to DuaText("เมื่อคุณได้รับคำชม", "โอ้อัลลอฮฺ ขออย่าทรงเอาฉันมารับผิดชอบในสิ่งที่พวกเขาพูด และโปรดอภัยให้ฉันในสิ่งที่พวกเขาไม่รู้ด้วย", "เมื่อได้ฟังคำชมตนเองแล้ว - การปฏิบัติของสหาย (RA).", "วิธีหลีกเลี่ยงความเย่อหยิ่งเมื่อได้รับคำชม"),
        "dua_non_muslim_sneezes" to DuaText("เมื่อคนที่ไม่ใช่มุสลิมจาม", "ขอให้อัลลอฮ์ทรงนำทางคุณและจัดการกิจการของคุณให้ถูกต้อง", "เมื่อผู้ที่ไม่ใช่มุสลิมจามและพูดว่า 'อัลฮัมดุลิ้ลลาห์'", "ชาวยิวจะจามใกล้กับศาสดาพยากรณ์ ﷺ โดยหวังว่าเขาจะพูดว่า 'Yarhamukallah' และเขาจะพูดแบบนี้"),
        "dua_reply_ahl_kitab_salam" to DuaText("ตอบกลับสลามของชาวคัมภีร์", "และต่อคุณ", "เมื่อชาวคัมภีร์ทักทายด้วยสลาม", "คำสั่งสอนของศาสดาพยากรณ์ ﷺ"),
        "dua_fasting_invited" to DuaText("เมื่อได้รับเชิญขณะถือศีลอด", "ฉันกำลังถือศีลอด", "เมื่อได้รับเชิญขณะอดอาหารหรือเมื่อมีคนทะเลาะกับคุณ", "หากผู้ถือศีลอดตอบรับคำเชิญ เขาควรอธิษฐานเผื่อเจ้าภาพ"),
        "dua_for_who_gave_drink" to DuaText("สำหรับใครก็ตามที่เลี้ยงฉัน", "โอ้อัลลอฮ์ โปรดให้อาหารแก่ผู้ที่ให้อาหารฉัน และให้เครื่องดื่มแก่ผู้ที่ให้ฉันดื่ม", "สำหรับใครก็ตามที่ให้อาหารหรือเครื่องดื่มแก่คุณ", "พระศาสดา ﷺ ได้ทำ dua นี้สำหรับอัล-มิคดัด (RA)"),
        "dua_eid_greeting" to DuaText("คำอวยพรวันอีด", "ขออัลลอฮ์ทรงตอบรับ (ความดี) จากเราและจากท่าน", "ถึงกันในวันอีด - การปฏิบัติของสหายผู้สูงศักดิ์ (RA)", "บรรดาสหายกล่าวเช่นนี้เมื่อพวกเขาพบกันในวันอีด"),
        "dua_wedding_night" to DuaText("สำหรับเจ้าสาวหลังนิกะห์", "โอ้ อัลลอฮฺ ฉันขอความคุ้มครองต่อพระองค์สำหรับความดีของเธอ และความดีแห่งธรรมชาติที่พระองค์ทรงสร้างเธอด้วย และฉันขอความคุ้มครองจากพระองค์ให้พ้นจากความชั่วร้ายของเธอ และความชั่วร้ายแห่งธรรมชาติที่พระองค์ทรงสร้างเธอด้วย", "หลังจากนิกะฮ์แล้ว ให้วางมือบนหน้าผากของภรรยา", "คำสอนของศาสดาพยากรณ์ ﷺ — การให้พรในการแต่งงาน"),
        "dua_istisqa_ibadak" to DuaText("รดน้ำคนรับใช้และสัตว์ของคุณ", "โอ้อัลลอฮ์ โปรดประทานน้ำแก่ผู้รับใช้ของพระองค์และสัตว์ของพระองค์ โปรดประทานความเมตตาของพระองค์ และประทานชีวิตแก่ดินแดนที่ตายแล้วของพระองค์", "ขอฝน (อิสติสกา)", "พระศาสดา ﷺ ทรงตั้งดุอานี้ให้ฝนตก"),
        "dua_seeing_clouds" to DuaText("มองเห็นเมฆดำ", "โอ้อัลลอฮ์ ฉันขอความคุ้มครองจากพระองค์ให้พ้นจากความชั่วร้ายของมัน", "เมื่อเห็นเมฆดำมืดบนท้องฟ้า หากฝนตก ให้กล่าวว่า “อัลลอฮุมมา ซัยยิบาน นาฟีอา”", "เมื่อเห็นเมฆ ศาสดา ﷺ จะละทิ้งสิ่งที่เขาทำอยู่และทำดุอานี้"),
        "dua_jamarat" to DuaText("การขว้างหินจามารัต", "อัลลอฮฺคือผู้ทรงยิ่งใหญ่", "ด้วยการโยนก้อนหินแต่ละก้อน", "ศาสดา ﷺ กล่าวตักบีร์ด้วยกรวดทุกก้อน จากนั้นหลังจากจัมเราะห์ตัวแรกและตัวที่สองก็เผชิญหน้ากับกิบลัตและดุอาอ์ยาว ๆ"),
        "dua_rabbi_ainni" to DuaText("ข้าแต่พระเจ้าของข้าพระองค์ โปรดช่วยข้าพระองค์ด้วยและไม่ทรงต่อต้านข้าพระองค์เลย", "ข้าแต่พระเจ้า โปรดช่วยฉันและอย่าช่วยเหลือผู้อื่นในการต่อต้านฉัน โปรดประทานชัยชนะแก่ฉัน และอย่าให้ผู้อื่นได้รับชัยชนะเหนือฉัน โปรดวางแผนสำหรับฉันและอย่าวางแผนต่อต้านฉัน ชี้ทางให้ฉันและชี้แนะทางที่ง่ายดายสำหรับฉัน และช่วยฉันต่อสู้กับใครก็ตามที่อธรรมฉัน", "ดุอาที่ครอบคลุมของศาสดาพยากรณ์ ﷺ (ส่วนเปิด)", "ดุอาที่รวบรวมทุกความช่วยเหลือในศาสนาและโลกนี้"),
        "dua_ati_nafsi_taqwaha" to DuaText("มอบจิตวิญญาณของฉันให้เป็นตักวา", "โอ้อัลลอฮ์ โปรดประทานให้จิตวิญญาณของฉันมีความยำเกรงและชำระมันให้บริสุทธิ์ เพราะพระองค์เป็นผู้ที่ดีที่สุดในการชำระให้บริสุทธิ์ คุณเป็นผู้พิทักษ์และเป็นเจ้านายของมัน", "เพื่อปฏิรูปและชำระตนให้บริสุทธิ์", "พระศาสดา ﷺ เคยทำดุอานี้"),
        "dua_iqsim_lana_khashyatik" to DuaText("ขอทรงโปรดให้ความเกรงกลัวพระองค์แก่เราเถิด", "โอ้อัลลอฮ์ โปรดประทานความกลัวต่อพระองค์ให้เรามากพอที่จะเข้ามาขวางกั้นเราและไม่เชื่อฟังพระองค์ เชื่อฟังมากพอที่จะนำเราไปสู่สวรรค์ของพระองค์ และมีความแน่นอนเพียงพอที่จะทำให้ภัยพิบัติในโลกนี้เป็นเรื่องง่ายสำหรับเรา ขอให้เราสนุกกับการฟัง การมองเห็น และกำลังของเราตราบเท่าที่พระองค์ทรงให้เรามีชีวิตอยู่ และทำให้พวกเขามีอายุยืนยาวกว่าเรา แก้แค้นผู้ที่ทำผิดต่อเรา ช่วยเราต่อสู้กับศัตรู อย่าปล่อยให้ความหายนะมาอยู่ในศาสนาของเรา อย่าทำให้โลกนี้เป็นกังวลมากที่สุดหรือจำกัดความรู้ของเรา และอย่าตั้งอยู่เหนือเราผู้ที่จะไม่แสดงความเมตตาต่อเรา", "เมื่อลุกขึ้นจากที่ชุมนุม - พระศาสดา ﷺ แทบจะไม่ลุกขึ้นโดยไม่ทำดุอานี้", "ดุอาที่ครอบคลุมเพื่อประโยชน์ของศาสนาโลกนี้และปรโลก"),
        "dua_infani_bima_allamtani" to DuaText("โปรดให้ประโยชน์แก่ฉันด้วยสิ่งที่คุณสอนฉัน", "โอ้อัลลอฮ์ โปรดทรงโปรดประทานแก่ฉันด้วยสิ่งที่พระองค์ทรงสอนฉัน สอนฉันในสิ่งที่เป็นประโยชน์แก่ฉัน และเพิ่มพูนความรู้แก่ฉัน", "ขณะแสวงหาความรู้หรือก่อนเรียน", "ดุอาสำหรับความรู้ที่เป็นประโยชน์และปฏิบัติตามนั้น"),
    )
}
